# تحديث أسبوعي (27 نوفمبر 2026)، الإصدار 1.1.1: حدث الأسبوع (يوروبا كليبر قرب الأرض)، وتاريخ مرورها في K267،
#  وحدثان في «سماء الشهر»: البدر العملاق 24 ديسمبر، والقمر مع المشتري والمريخ 27 ديسمبر.
import os
P=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','src','ai-horizon.html')
s=open(P,encoding='utf-8').read()
def rep(o,n,count=1):
    global s
    assert s.count(o)==count,(s.count(o),o[:70])
    s=s.replace(o,n)
rep('''const WEEK_EVENT={title:"بيبي كولومبو تدخل مدار عطارد",note:"بعد رحلة دامت 8 سنوات، تدخل المركبة الأوروبية اليابانية مدار عطارد، ثم تنفصل مركبتاها في ديسمبر.",date:"2026-11-21",until:"2026-11-24",entry:"K266",after:"أكدت وكالة الفضاء الأوروبية نجاح دخول بيبي كولومبو مدار عطارد."};''',
'''const WEEK_EVENT={title:"يوروبا كليبر تمرّ قرب الأرض",note:"تمرّ مركبة ناسا على بُعد نحو 3,200 كيلومتر من الأرض لتكسب سرعة من جاذبيتها في طريقها إلى المشتري.",date:"2026-12-03",until:"2026-12-05",entry:"K267",after:"كان موعد مرور يوروبا كليبر قرب الأرض في 3 ديسمبر، ومن المخطط أن تصل إلى المشتري في أبريل 2030."};''')
rep('وتمرّ قرب الأرض في ديسمبر 2026 على بُعد نحو 3,200 كيلومتر.','وتمرّ قرب الأرض في 3 ديسمبر 2026 على بُعد نحو 3,200 كيلومتر.')
rep('"K267": ["https://science.nasa.gov/mission/europa-clipper/mission-timeline/", "ناسا"]','"K267": ["https://www.jpl.nasa.gov/news/nasas-europa-clipper-zooming-by-earth-on-way-to-jupiters-icy-moon/", "ناسا"]')
rep('''    {t:"الكسوف الكلي فوق جدة ومكة",''','''    {t:"البدر العملاق: أقرب بدر في السنة",d:new Date(Date.UTC(2026,11,24,1,28)),note:"آخر بدر في 2026 وأقربها إلى الأرض، فيبدو أكبر وأسطع قليلًا. انظر إليه في الشرق بعد غروب الشمس ليلة 23 ديسمبر، ويكتمل قبيل فجر 24 ديسمبر. يُرى بالعين.",once:true},
    {t:"القمر مع المشتري والمريخ",d:new Date(Date.UTC(2026,11,27,18,0)),note:"مساءً، بعد شروق القمر في الشرق، يظهر قرب المشتري اللامع والمريخ الأحمر ونجم قلب الأسد. يُرى بالعين.",once:true},
    {t:"الكسوف الكلي فوق جدة ومكة",''')
rep(''' {v:"1.1",date:"2026-11-27",title:"تطوير أفق",items:[''',''' {v:"1.1",date:"2026-11-27",title:"تطوير أفق",fixes:[{v:"1.1.1",date:"2026-11-27",text:"تحديث أسبوعي: حدث الأسبوع مرور يوروبا كليبر قرب الأرض، وموعدان جديدان في «أحداث قادمة»: البدر العملاق والقمر مع المشتري والمريخ."}],items:[''')
rep('<small class="ver">الإصدار 1.1 · آخر تحديث 27 نوفمبر 2026</small>','<small class="ver">الإصدار 1.1.1 · آخر تحديث 27 نوفمبر 2026</small>')
